      if(this.state==='serviceApproach'){
        const target=this.stationServicePoint(),stop=this.stationStopPoint();const auto=updateExteriorTargetAutopilot(this,target,stop,d=>this.shiftHost(this.host,d),dt);
        if(auto.arrived)this.beginOrderTransfer();return true
      }
      if(this.state==='orderTransfer'){this.updateOrderTransfer(dt);return true}
