        ctx.save();ctx.strokeStyle=C.c;ctx.lineWidth=VECTOR_LINE_WIDTH;ctx.globalAlpha=.68;
        for(let i=0;i<7;i++){const t=.10+(((i/7)+flow)%1)*.82,cx=lerp(a.x,b.x,t),cy=lerp(a.y,b.y,t),half=lerp(8,Math.min(34,10+len*.055),t),bow=lerp(5,18,t);ctx.beginPath();ctx.moveTo(cx+px*half,cy+py*half);ctx.quadraticCurveTo(cx+ux*bow,cy+uy*bow,cx-px*half,cy-py*half);ctx.stroke()}
