    if(!this.active||mode!=='play'||this.autopilotActive())return;const t=this.markerTarget();if(!t?.p)return;const q=camPoint(t.p);let r=13,p=null,on=false;if(q[2]>.15){p=projectCam(q);on=!!(p&&p.x>=0&&p.x<=W&&p.y>=0&&p.y<=viewH)}if(!on)p=hudEdgeCue(q,r);if(!p)return;const col=C.y,x=p.x,y=p.y;line(x-r,y,x,y-r,col,1.2,.96);line(x,y-r,x+r,y,col,1.2,.96);line(x+r,y,x,y+r,col,1.2,.96);line(x,y+r,x-r,y,col,1.2,.96);drawHudMarkerLabel(t.label,x,y,r,col)
